    conv, bn, dropout, pool, _flatten, linear, _loss = layers
    if not bn._training:
        raise ValueError("BatchNorm2D 必须处于训练态")
    if not dropout._training:
        raise ValueError("Dropout 必须处于训练态")

    # 配置须同 fitnorm（_build_norm_layers）。
    if conv._stride != (1, 1):
