    # 形状与叶值契约（同 benchmark model：固定形状、叶值限有限 float）。
    tensors = (
        (conv._weights, 4, (2, 1, 1, 1), "conv values"),
        (conv._bias, 1, (2,), "conv bias"),
        (bn._gamma, 1, (2,), "gamma"),
        (bn._beta, 1, (2,), "beta"),
        (bn.running_mean, 1, (2,), "running_mean"),
        (bn.running_var, 1, (2,), "running_var"),
        (linear._weights, 2, (2, 2), "linear values"),
